arguments.file_text:
@page "/chat"
@using sv_ccc01a6c9c22404ca249e161242eb6b6.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    @if (_activeChannel is not null)
    {
        <div class="chat-main @(_threadOpen ? "thread-open" : "")">
            <MessageArea Channel="_activeChannel"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         OnOpenThread="OpenThread"
                         OnSendMessage="SendMessage"
                         OnReaction="HandleReaction"
                         OnLoadMore="LoadMoreMessages" />
        </div>

        @if (_threadOpen && _threadRootMessage is not null)
        {
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        }
    }
</div>

@code {
    private List<Channel> _channels = new();
    private Channel? _activeChannel;
    private int _activeChannelId;
    private List<Message> _messages = new();
    private List<ThreadSummary> _threadSummaries = new();

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = new();

    private const int PageSize = 30;
    private int _skip;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _skip = 0;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _threadSummaries = BuildThreadSummaries(_messages);
        CloseThread();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var message = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(message);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect new reaction
        if (_activeChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _skip + PageSize);
        }
    }

    private async Task OpenThread(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summaries
        _threadSummaries = BuildThreadSummaries(_messages);
    }

    private async Task LoadMoreMessages()
    {
        if (_activeChannel is null) return;
        _skip += PageSize;
        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _skip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
        }
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> messages)
    {
        // Build thread summaries from messages that have replies
        var rootIds = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
        return rootIds;
    }
}

/* === Chat Layout === */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* === Channel Sidebar === */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    border-radius: 4px;
    margin: 2px 8px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

.channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #72767d;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    border-radius: 10px;
    padding: 1px 6px;
    font-size: 0.7rem;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
}

/* === Main Message Area === */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    min-width: 0;
}

.chat-main.thread-open {
    max-width: 55%;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

